head.b:skin:
:root{--g:rgba(255,255,255,.07);--gb:rgba(255,255,255,.15);--t:#eef3fb;--m:#9fb0c9;--a:#2dd4bf;--w:#f5c451;--r:#fb7185}
*{box-sizing:border-box;margin:0}
body{font-family:'Hind Siliguri',system-ui,sans-serif;color:var(--t);min-height:100vh;background:#070d1c;line-height:1.6}
.bg{position:fixed;inset:0;z-index:-1;background:radial-gradient(55vw 50vw at 8% -5%,#1d4ed8aa 0,transparent 60%),radial-gradient(45vw 45vw at 100% 10%,#0d9488aa 0,transparent 60%),radial-gradient(50vw 50vw at 60% 110%,#6d28d977 0,transparent 60%),#070d1c}
.glass{background:linear-gradient(145deg,rgba(255,255,255,.10),rgba(255,255,255,.04));border:1px solid var(--gb);backdrop-filter:blur(22px) saturate(150%);-webkit-backdrop-filter:blur(22px) saturate(150%);border-radius:18px;box-shadow:0 10px 40px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.12)}
nav{position:sticky;top:10px;margin:10px auto;max-width:1200px;width:calc(100% - 20px);padding:8px 14px;display:flex;gap:4px;align-items:center;flex-wrap:wrap;z-index:5}
.logo{font-weight:700;font-size:21px;margin-right:auto;display:flex;align-items:center;gap:8px}.logo b{color:var(--a)}
.logo i{font-style:normal;width:30px;height:30px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(135deg,#2dd4bf,#3b82f6);color:#04121f;font-size:16px}
nav a{padding:6px 12px;border-radius:10px;cursor:pointer;color:var(--m);font-size:15px}nav a.on,nav a:hover{background:rgba(255,255,255,.1);color:var(--t)}
.wrap{max-width:1200px;margin:auto;padding:10px;display:grid;grid-template-columns:1fr 270px;gap:16px}
@media(max-width:900px){.wrap{grid-template-columns:1fr}}
.card{padding:20px;margin-bottom:16px}
h1{font-size:clamp(28px,5vw,44px);line-height:1.2;font-weight:700;letter-spacing:-.01em}h2{font-size:20px;margin-bottom:10px;font-weight:600}h3{font-size:17px;font-weight:600}
.sub{color:var(--m)}.lead{font-size:17px;margin:12px 0 18px;max-width:52ch}
.btn{background:linear-gradient(135deg,#2dd4bf,#34d399);color:#04201d;border:0;border-radius:11px;padding:9px 18px;font-family:inherit;font-size:15px;font-weight:600;cursor:pointer;transition:filter .15s}
.btn:hover{filter:brightness(1.1)}.btn.o{background:rgba(255,255,255,.06);color:var(--t);border:1px solid var(--gb)}.btn.s{padding:4px 11px;font-size:13px}
.btn:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,nav a:focus-visible{outline:2px solid var(--a);outline-offset:2px}
input,select,textarea{width:100%;background:rgba(5,12,28,.45);border:1px solid var(--gb);color:var(--t);border-radius:11px;padding:9px 12px;font:inherit;margin:4px 0 9px}
option{color:#000}label{font-size:13px;color:var(--m)}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}.grid>.card{margin:0}
.chip{display:inline-block;padding:2px 11px;border-radius:20px;background:rgba(255,255,255,.08);border:1px solid var(--gb);font-size:13px;margin:2px}
.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:#64748b;margin-right:5px}.dot.on{background:#22c55e;box-shadow:0 0 8px #22c55e}
.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.sp{margin-left:auto}
.amt{font-size:30px;font-weight:700;color:var(--w)}
.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:20px;align-items:center;padding:34px}@media(max-width:700px){.hero{grid-template-columns:1fr;padding:22px}}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:16px}.stats .card{margin:0;text-align:center;padding:14px}.stats b{font-size:24px;color:var(--a);display:block}
.ft{border-left:3px solid var(--a);padding-left:12px}.ft b{display:block}
.bar{height:8px;border-radius:8px;background:rgba(255,255,255,.1);overflow:hidden;margin:8px 0}.bar i{display:block;height:100%;background:linear-gradient(90deg,#2dd4bf,#3b82f6)}
.av{width:52px;height:52px;border-radius:50%;object-fit:cover;background:linear-gradient(135deg,#1e3a8a,#0d9488);display:grid;place-items:center;font-weight:700;flex:none;border:2px solid var(--gb)}.av.l{width:96px;height:96px;font-size:32px}
.vb{color:#22c55e;font-size:13px}.lnk{color:var(--a);cursor:pointer;text-decoration:underline}
.cols{display:grid;grid-template-columns:260px 1fr;gap:16px}@media(max-width:700px){.cols{grid-template-columns:1fr}}.cols>.card{margin:0}
#modal{position:fixed;inset:0;background:rgba(3,8,20,.65);display:none;align-items:center;justify-content:center;z-index:20;padding:12px}
#modal .box{max-width:540px;width:100%;max-height:90vh;overflow:auto;padding:22px;background:rgba(12,22,44,.9)}
.msg{padding:6px 10px;border-radius:12px;margin:4px 0;max-width:80%;background:rgba(255,255,255,.08)}.msg.me{margin-left:auto;background:#2dd4bf30}
.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);padding:10px 18px;z-index:30;background:rgba(12,22,44,.92)}
.ok{color:#22c55e}.no{color:var(--r)}.st{color:var(--w)}
iframe{width:100%;aspect-ratio:16/9;border:0;border-radius:12px}
.pk{text-align:center}.pk b{font-size:22px;color:var(--a)}
footer{max-width:1200px;margin:10px auto 30px;padding:18px 20px;text-align:center;font-size:13px}

body.script:
//

const FEE=5,DEV=2.5; // মোট ৫% ফি; এর মধ্যে ২.৫% উন্নয়ন তহবিল
const CATS=['মাইক্রোসফট অফিস','গ্রাফিক্স ডিজাইন','ডাটা এন্ট্রি','ফটোশপ','ডাটা অ্যানালাইসিস','ব্র্যান্ড প্রমোশন','মার্কেটিং','ফেসবুক মনিটাইজেশন','ফেসবুক পে-আউট সেটআপ','ফেসবুক অ্যাড রানিং','ইউটিউব মনিটাইজেশন','ইউটিউব পে সেটআপ','স্বশরীরে কাজ','উকিল হায়ার','ডেলিভারি ম্যান হায়ার','দিনমজুর হায়ার','পর্যটন গাইড হায়ার','ব্যবস্থাপক হায়ার','গার্মেন্টস কর্মী হায়ার','কম্পিউটার অপারেটর','ভিডিও এডিটিং','ওয়েব ডেভেলপমেন্ট','অনুবাদ ও কনটেন্ট রাইটিং','অন্যান্য'];
const PK=[[100,300],[200,500],[300,700],[400,800],[500,850],[600,900],[700,930],[800,950],[900,970],[1000,1000]];
const bn=n=>Number(n).toLocaleString('bn-BD');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const bad=t=>/([0-9০-৯][\s-]?){8,}|[\w.-]+@[\w.-]+|@|whats?\s?app|facebook|fb\.com|messenger|telegram|instagram|imo|হোয়াটস|ফেসবুক|ইমেইল|টেলিগ্রাম|মেসেঞ্জার/i.test(t);
let S;try{S=JSON.parse(localStorage.getItem('mt'))}catch(e){}
S=S||{users:[],cur:null,jobs:[],prods:[],ads:[],seq:1,jid:1};
const save=()=>{try{localStorage.setItem('mt',JSON.stringify(S))}catch(e){}};
const me=()=>S.users.find(u=>u.id===S.cur),U=id=>S.users.find(u=>u.id===id);
let tab='home',cat='',q='';
const $=id=>document.getElementById(id),v=id=>($(id)||{}).value||'';
function toast(m){const d=document.createElement('div');d.className='toast glass';d.textContent=m;document.body.appendChild(d);setTimeout(()=>d.remove(),2800)}
function modal(h){$('mbox').innerHTML=h;$('modal').style.display='flex'}
function closeM(){$('modal').style.display='none'}
$('modal').onclick=e=>{if(e.target.id=='modal')closeM()};
function note(id,m){const u=U(id);if(u){u.notes.unshift({m,t:new Date().toLocaleString('bn-BD'),r:0});save()}}
function go(t){tab=t;render()}
function verified(u){return u.ver.m&&u.ver.n&&u.ver.e&&u.doc&&u.photo}
function need(){const u=me();if(!u){toast('আগে লগইন বা রেজিস্ট্রেশন করুন');reg();return 0}if(!verified(u)){toast('প্রোফাইল ভেরিফিকেশন সম্পূর্ণ করুন');go('dash');return 0}return u}
function nav(){const u=me(),un=u?u.notes.filter(n=>!n.r).length:0;
 const t=[['home','হোম'],['free','ফ্রিল্যান্সার'],['jobs','কাজ'],['mkt','পণ্য বাজার'],['prof','প্রোফাইল'],['dash','ড্যাশবোর্ড'+(un?' 🔔'+bn(un):'')]];
 $('nav').innerHTML='<div class="logo"><i>M</i><span>Money<b>Tag</b></span></div>'+t.map(x=>`<a tabindex=0 class="${tab==x[0]?'on':''}" onclick="go('${x[0]}')">${x[1]}</a>`).join('')+(u?`<span class="chip">${av(u,22)}<span class="dot on"></span>${esc(u.id)}</span><button class="btn o s" onclick="logout()">লগআউট</button>`:'<button class="btn o s" onclick="login()">লগইন</button><button class="btn s" onclick="reg()">রেজিস্ট্রেশন</button>')}
function av(u,s){s=s||48;const st=`width:${s}px;height:${s}px;font-size:${s/2.4}px`;return u&&u.img?`<img class="av" style="${st}" src="${u.img}" alt="">`:`<span class="av" style="${st}">${esc((u&&u.id||'?')[0])}</span>`}
function adsPanel(){$('ads').innerHTML='<div class="glass card"><h3>বিজ্ঞাপন</h3><p class="sub" style="font-size:13px">ক্লায়েন্টদের প্রমোটেড কাজ</p></div>'+(S.ads.length?S.ads.map(a=>{const m=a.v.match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/);return`<div class="glass card"><b>${esc(a.t)}</b>${m?`<iframe src="https://www.youtube.com/embed/${m[1]}" allowfullscreen></iframe>`:''}<p class="sub">${esc(a.d)}</p></div>`}).join(''):'<div class="glass card sub">এখানে আপনার ভিডিও বিজ্ঞাপন দেখান। ড্যাশবোর্ড থেকে প্রচার শুরু করুন।</div>')}
function render(){nav();adsPanel();$('app').innerHTML=({home,free,jobs,mkt,dash,prof})[tab]();window.scrollTo(0,0)}
function home(){return`<section class="glass card hero"><div><span class="chip">বাংলাদেশের নিরাপদ কাজের বাজার</span><h1 style="margin-top:10px">দক্ষতাকে আয়ে বদলান, কোনো ঝুঁকি ছাড়াই।</h1><p class="sub lead">অনলাইন ও স্বশরীরে কাজের জন্য ভেরিফায়েড ফ্রিল্যান্সার ও ক্লায়েন্ট এক জায়গায়। কাজ বুঝে পাওয়ার আগে টাকা এসক্রোতে সুরক্ষিত থাকে।</p><div class="row"><button class="btn" onclick="reg('f')">ফ্রিল্যান্সার হিসেবে যোগ দিন</button><button class="btn o" onclick="reg('b')">কাজ পোস্ট করুন</button></div></div><div class="glass card" style="margin:0"><span class="sub">এসক্রো পেমেন্টের উদাহরণ</span><div class="amt">৳৫,০০০</div><div class="bar"><i style="width:75%"></i></div><p class="sub" style="font-size:14px">কাজ জমা → ক্লায়েন্টের নিশ্চিতকরণ → ফ্রিল্যান্সারের ওয়ালেটে ৳৪,৭৫০</p></div></section>
<div class="stats"><div class="glass card"><b>${bn(CATS.length)}+</b>কাজের ক্ষেত্র</div><div class="glass card"><b>${bn(100)}</b>ফ্রি কানেক্ট</div><div class="glass card"><b>${bn(FEE)}%</b>সার্ভিস ফি</div><div class="glass card"><b>২৪/৭</b>নোটিফিকেশন</div></div>
<div class="glass card"><h2>কেন MoneyTag</h2><div class="grid"><div class="ft"><b>এসক্রো পেমেন্ট</b><span class="sub">কাজ নিশ্চিত না হওয়া পর্যন্ত টাকা সুরক্ষিত।</span></div><div class="ft"><b>ভেরিফায়েড প্রোফাইল</b><span class="sub">মোবাইল, ইমেইল, এনআইডি ও ছবি যাচাই।</span></div><div class="ft"><b>নিরাপদ চ্যাট</b><span class="sub">ব্যক্তিগত যোগাযোগের তথ্য শেয়ার আটকানো।</span></div><div class="ft"><b>ওয়ালেট</b><span class="sub">বিকাশ, নগদ, রকেট ও ব্যাংক থেকে জমা।</span></div></div></div>
<div class="glass card"><h2>কাজের ক্ষেত্র</h2>${CATS.map(c=>`<span class="chip" style="cursor:pointer" onclick="cat='${c}';go('free')">${c}</span>`).join('')}</div>
<div class="glass card"><h2>কানেক্ট প্যাকেজ</h2><p class="sub">নতুন ফ্রিল্যান্সার পান ১০০ কানেক্ট ফ্রি। প্রতি কাজে আবেদনে ১ কানেক্ট লাগে।</p><br><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(130px,1fr))">${PK.map(p=>`<div class="glass card pk"><b>${bn(p[0])}</b><br><span class="sub">কানেক্ট</span><br><span class="amt" style="font-size:19px">৳${bn(p[1])}</span><br><button class="btn s" style="margin-top:6px" onclick="buyC(${p[0]},${p[1]})">কিনুন</button></div>`).join('')}</div></div>
<div class="glass card"><h2>কীভাবে কাজ করে</h2><div class="grid"><div class="ft"><b>১. কাজ পোস্ট</b><span class="sub">ক্লায়েন্ট বিবরণ ও বাজেট দেন।</span></div><div class="ft"><b>২. আবেদন ও চ্যাট</b><span class="sub">ফ্রিল্যান্সার আবেদন করেন, দর ঠিক হয়।</span></div><div class="ft"><b>৩. এসক্রো</b><span class="sub">নিয়োগের সময় ওয়ালেট থেকে টাকা রাখা হয়।</span></div><div class="ft"><b>৪. জমা ও পেমেন্ট</b><span class="sub">নিশ্চিত হলে ${bn(FEE)}% ফি বাদে টাকা যায়।</span></div><div class="ft"><b>৫. রিভিউ</b><span class="sub">দুই পক্ষই রিভিউ দেন।</span></div></div></div>`}
function stars(u){const r=u.rev||[];return r.length?'★ '+bn((r.reduce((a,b)=>a+b.s,0)/r.length).toFixed(1))+' ('+bn(r.length)+')':'নতুন'}
const DEMO=[{id:'F-100001',role:'f',title:'ডাটা এন্ট্রি ও এক্সেল বিশেষজ্ঞ',bio:'দ্রুত ও নির্ভুল ডাটা এন্ট্রি, এক্সেল রিপোর্ট ও ফর্মুলার কাজ করি।',loc:'ঢাকা',rate:500,lang:'বাংলা, ইংরেজি',skills:'ডাটা এন্ট্রি, মাইক্রোসফট অফিস',rev:[{s:5,c:'সময়মতো নিখুঁত কাজ'}],on:1,port:[]},{id:'F-100002',role:'f',title:'গ্রাফিক ডিজাইনার',bio:'লোগো, ব্যানার ও সোশ্যাল মিডিয়া ডিজাইন।',loc:'চট্টগ্রাম',rate:800,lang:'বাংলা',skills:'গ্রাফিক্স ডিজাইন, ফটোশপ',rev:[{s:4,c:'ভালো ডিজাইন'}],on:0,port:[]}];
const okv=u=>u.ver?verified(u):1;
function free(){const all=[...S.users.filter(u=>u.role=='f'),...DEMO].filter(u=>(!cat||(u.skills||'').includes(cat))&&(!q||((u.skills||'')+(u.title||'')+u.id).includes(q))).sort((a,b)=>(b.promo||0)-(a.promo||0));
 return`<div class="glass card"><h2>ফ্রিল্যান্সার খুঁজুন</h2><div class="row"><input style="flex:1" placeholder="দক্ষতা বা আইডি লিখুন" value="${esc(q)}" onchange="q=this.value;render()"><select style="flex:1" onchange="cat=this.value;render()"><option value="">সব ক্ষেত্র</option>${CATS.map(c=>`<option ${c==cat?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="grid">${all.map(u=>`<div class="glass card"><div class="row">${av(u)}<div><span class="dot ${u.on||u.id==S.cur?'on':''}"></span><b>${u.id}</b>${okv(u)?' <span class="vb">✔ ভেরিফায়েড</span>':''}<br><span class="sub">${stars(u)}</span></div></div><p style="margin-top:8px"><b>${esc(u.title||'নতুন ফ্রিল্যান্সার')}</b></p><p class="sub" style="font-size:14px">${esc(u.skills||'দক্ষতা যোগ হয়নি')}</p>${u.rate?`<p class="st">৳${bn(u.rate)} থেকে শুরু</p>`:''}${u.promo?'<span class="chip st">প্রোমোটেড</span>':''}<button class="btn o s" style="margin-top:8px" onclick="viewP('${u.id}')">প্রোফাইল দেখুন</button></div>`).join('')||'<p class="sub">এই ক্ষেত্রে কেউ নেই।</p>'}</div>`}
function viewP(id){const u=U(id)||DEMO.find(d=>d.id==id);if(!u)return;const f=u.role=='f';
 modal(`<div class="row">${av(u,96)}<div><h2 style="margin:0">${esc(u.id)}</h2><span class="dot ${u.on||u.id==S.cur?'on':''}"></span>${u.on||u.id==S.cur?'অনলাইন':'অফলাইন'}${okv(u)?' · <span class="vb">✔ ভেরিফায়েড</span>':''}<br><span class="sub">${stars(u)}</span></div><button class="btn o s sp" onclick="closeM()">বন্ধ</button></div>
 <p style="margin-top:12px"><b>${esc(f?(u.title||'নতুন ফ্রিল্যান্সার'):(u.company||'ক্লায়েন্ট'))}</b>${u.loc?' · '+esc(u.loc):''}</p><p class="sub">${esc(u.bio||'কোনো পরিচিতি নেই।')}</p>
 ${f?`<p style="margin-top:8px">${(u.skills||'').split(', ').filter(Boolean).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</p>${u.rate?`<p class="st">৳${bn(u.rate)} থেকে শুরু</p>`:''}${u.lang?`<p class="sub">ভাষা: ${esc(u.lang)}</p>`:''}${(u.port||[]).length?'<h3 style="margin-top:10px">পোর্টফোলিও</h3>'+u.port.map(x=>`<p>• ${esc(x.t)}${x.l?` – <a class="lnk" href="${esc(x.l)}" target="_blank" rel="noopener noreferrer">দেখুন</a>`:''}</p>`).join(''):''}`:''}
 <h3 style="margin-top:10px">রিভিউ</h3>${(u.rev||[]).map(r=>`<p>★ ${bn(r.s)} <span class="sub">${esc(r.c)}</span></p>`).join('')||'<p class="sub">এখনো রিভিউ নেই।</p>'}`)}
function jobs(){const u=me();
 const form=u&&u.role=='b'?`<div class="glass card"><h2>নতুন কাজ পোস্ট</h2><input id="jt" placeholder="কাজের শিরোনাম"><select id="jc">${CATS.map(c=>`<option>${c}</option>`).join('')}</select><input id="jb" type="number" placeholder="বাজেট (৳)"><textarea id="jd" placeholder="কাজের বিবরণ"></textarea><button class="btn" onclick="postJob()">কাজ পোস্ট করুন</button></div>`:'';
 const L=S.jobs.slice().reverse().map(j=>{const by=U(j.by),mine=u&&j.by==u.id,fr=u&&j.hire==u.id;
 const ap=u&&u.role=='f'&&j.st=='open'&&!j.ap.includes(u.id)?`<button class="btn s" onclick="apply(${j.id})">আবেদন (১ কানেক্ট)</button>`:'';
 const hire=mine&&j.st=='open'?j.ap.map(f=>`<button class="btn o s" onclick="hire(${j.id},'${f}')">${f}-কে নিয়োগ</button>`).join(''):'';
 const sub=fr&&j.st=='progress'?`<label class="btn s" style="display:inline-block">ফাইল জমা দিন<input type="file" hidden onchange="submitW(${j.id},this)"></label>`:'';
 const cf=mine&&j.st=='review'?`<button class="btn s" onclick="confirmW(${j.id})">নিশ্চিত করে পেমেন্ট দিন</button>`:'';
 const rv=j.st=='done'&&(mine||fr)&&!j.rv[u.id]?`<button class="btn s" onclick="review(${j.id})">রিভিউ দিন</button>`:'';
 const ch=(mine||fr)&&j.hire||(mine&&j.ap.length)?`<button class="btn o s" onclick="chat(${j.id})">💬 চ্যাট</button>`:'';
 return`<div class="glass card"><div class="row"><h3>${esc(j.t)}</h3><span class="chip">${esc(j.c)}</span><span class="sp amt" style="font-size:20px">৳${bn(j.b)}</span></div><p class="sub">${esc(j.d)}</p><p style="font-size:13px"><span class="dot ${by&&by.id==S.cur?'on':''}"></span><a class="lnk" onclick="viewP('${j.by}')">${j.by}</a> · অবস্থা: <b class="st">${{open:'খোলা',progress:'চলমান',review:'যাচাইয়ের অপেক্ষায়',done:'সম্পন্ন'}[j.st]}</b> · আবেদন ${bn(j.ap.length)}</p>${j.files.map(f=>`<span class="chip">📎 ${esc(f)}</span>`).join('')}<div class="row" style="margin-top:6px">${ap}${hire}${sub}${cf}${rv}${ch}</div></div>`}).join('')||'<div class="glass card sub">এখনো কোনো কাজ নেই। ক্লায়েন্ট হিসেবে প্রথম কাজটি পোস্ট করুন।</div>';
 return form+L}
function mkt(){const u=me();return`${u?`<div class="glass card"><h2>পণ্য বিক্রি করুন</h2><input id="pt" placeholder="পণ্যের নাম"><input id="pp" type="number" placeholder="দাম (৳)"><textarea id="pd" placeholder="বিবরণ"></textarea><button class="btn" onclick="postProd()">পণ্য পোস্ট করুন</button></div>`:''}<div class="glass card"><h2>পণ্য বাজার</h2><p class="sub">ক্রয় শুধু ওয়ালেট ব্যালেন্স দিয়ে।</p></div><div class="grid">${S.prods.map((p,i)=>`<div class="glass card" style="margin:0"><h3>${esc(p.t)}</h3><p class="sub">${esc(p.d)}</p><p class="amt" style="font-size:22px">৳${bn(p.p)}</p><p style="font-size:12px">${p.by}</p>${p.sold?'<span class="chip no">বিক্রিত</span>':`<button class="btn s" onclick="buyP(${i})">ওয়ালেটে কিনুন</button>`}</div>`).join('')||'<p class="sub">এখনো কোনো পণ্য নেই।</p>'}</div>`}
function dash(){const u=me();if(!u)return'<div class="glass card"><h2>ড্যাশবোর্ড</h2><p class="sub">দেখতে লগইন করুন।</p><br><button class="btn" onclick="reg()">রেজিস্ট্রেশন</button> <button class="btn o" onclick="login()">লগইন</button></div>';
 const V=(k,l)=>`<div class="row"><span class="${u.ver[k]?'ok':'no'}">${u.ver[k]?'✔':'✖'}</span> ${l}${u.ver[k]?'':`<button class="btn s sp" onclick="verify('${k}')">ভেরিফাই</button>`}</div>`;
 const up=(k,l)=>`<div class="row"><span class="${u[k]?'ok':'no'}">${u[k]?'✔':'✖'}</span> ${l}${u[k]?'':`<label class="btn s sp">আপলোড<input type="file" accept="image/*" hidden onchange="upl('${k}',this)"></label>`}</div>`;
 const tx=(u.tx||[]).slice().reverse().map((t,i,a)=>`<div class="row" style="font-size:13px">${t.k} ৳${bn(t.a)} <span class="sub">${esc(t.n||'')}</span><span class="sp ${t.s=='ok'?'ok':'st'}">${t.s=='ok'?'ভেরিফায়েড':'যাচাই বাকি'}</span>${t.s!='ok'?`<button class="btn o s" onclick="vtx(${a.length-1-i})">ভেরিফাই (ডেমো)</button>`:''}</div>`).join('');
 return`<div class="glass card"><div class="row"><h2>${esc(u.name)}${u.company?' · '+esc(u.company):''}</h2><span class="chip">${u.role=='f'?'ফ্রিল্যান্সার':'ক্লায়েন্ট'}</span><span class="chip">${u.id}</span><span class="sp"><span class="dot on"></span>অনলাইন</span></div>
<div class="row" style="margin-top:6px"><div><span class="sub">ওয়ালেট</span><div class="amt">৳${bn(u.wallet)}</div></div>${u.role=='f'?`<div class="sp"><span class="sub">কানেক্ট</span><div class="amt">${bn(u.connects)}</div></div>`:''}</div></div>
<div class="glass card"><h2>ভেরিফিকেশন</h2>${V('m','মোবাইল: '+esc(u.phone))}${V('e','ইমেইল: '+esc(u.email))}${V('n','এনআইডি নম্বর: '+esc(u.nid))}${up('doc','এনআইডি / জন্মনিবন্ধনের ছবি')}${up('photo','প্রোফাইল ছবি')}${u.company?up('cdoc','কোম্পানির কাগজপত্র'):''}<p class="sub" style="font-size:12px">${verified(u)?'আপনার প্রোফাইল ভেরিফায়েড।':'সব ধাপ শেষ না হলে কাজ, আবেদন ও লেনদেন বন্ধ থাকবে।'}</p></div>
<div class="glass card"><h2>টাকা জমা</h2><select id="dm"><option>বিকাশ</option><option>নগদ</option><option>রকেট</option><option>ব্যাংক</option></select><input id="da" type="number" placeholder="পরিমাণ (৳)"><input id="dt" placeholder="ট্রানজেকশন আইডি (TrxID)"><button class="btn" onclick="dep()">জমা সাবমিট করুন</button><br><br>${tx||'<p class="sub">কোনো লেনদেন নেই।</p>'}</div>
${u.role=='f'?`<div class="glass card"><h2>প্রোফাইল প্রোমোশন</h2><p class="sub">৳৫০ দিয়ে সার্চে সবার উপরে দেখান।</p><br><button class="btn" onclick="promo()">${u.promo?'প্রোমোটেড ✔':'৳৫০ দিয়ে প্রোমোট করুন'}</button></div>`:`<div class="glass card"><h2>ভিডিও বিজ্ঞাপন (৳১০০)</h2><input id="at" placeholder="শিরোনাম"><input id="av" placeholder="ইউটিউব ভিডিও লিংক"><textarea id="ad" placeholder="ছোট বিবরণ"></textarea><button class="btn" onclick="adBuy()">প্রচার শুরু করুন</button></div>`}
<div class="glass card"><h2>নোটিফিকেশন</h2>${u.notes.map(n=>`<p style="font-size:14px">🔔 ${esc(n.m)} <span class="sub">${n.t}</span></p>`).join('')||'<p class="sub">কিছু নেই।</p>'}</div>`;}
function reg(r){modal(`<h2>রেজিস্ট্রেশন</h2><label>ধরন</label><select id="rr"><option value="f" ${r=='f'?'selected':''}>ফ্রিল্যান্সার</option><option value="b" ${r=='b'?'selected':''}>বায়ার / ক্লায়েন্ট</option></select><input id="rn" placeholder="পূর্ণ নাম"><input id="re" type="email" placeholder="ইমেইল"><input id="rp" placeholder="মোবাইল নম্বর"><input id="ri" placeholder="এনআইডি / জন্মনিবন্ধন নম্বর"><input id="rc" placeholder="কোম্পানির নাম (ঐচ্ছিক, শুধু ক্লায়েন্ট)"><button class="btn" onclick="doReg()">অ্যাকাউন্ট খুলুন</button>`)}
function doReg(){const n=v('rn').trim(),e=v('re').trim(),p=v('rp').trim(),i=v('ri').trim(),r=v('rr');if(!n||!e||!p||!i)return toast('সব ঘর পূরণ করুন');
 const u={id:(r=='f'?'F-':'B-')+(100100+S.seq++),name:n,email:e,phone:p,nid:i,role:r,ver:{m:0,e:0,n:0},doc:0,photo:0,wallet:0,connects:r=='f'?100:0,notes:[],tx:[],skills:'',rev:[],company:r=='b'?v('rc').trim():'',promo:0};
 S.users.push(u);S.cur=u.id;note(u.id,'স্বাগতম! প্রোফাইল ভেরিফিকেশন সম্পূর্ণ করুন।'+(r=='f'?' আপনি ১০০ ফ্রি কানেক্ট পেয়েছেন।':''));save();closeM();toast('আপনার আইডি: '+u.id);go('dash')}
function login(){modal(`<h2>লগইন</h2><input id="li" placeholder="আপনার আইডি (যেমন F-100100)"><button class="btn" onclick="doLogin()">লগইন</button>`)}
function doLogin(){const u=U(v('li').trim());if(!u)return toast('এই আইডি পাওয়া যায়নি');S.cur=u.id;save();closeM();go('dash')}
function logout(){S.cur=null;save();go('home')}
function verify(k){const c=String(Math.floor(1e5+Math.random()*9e5));const x=prompt('ডেমো কোড: '+c+'\nকোডটি লিখুন');if(x==c){me().ver[k]=1;save();render();toast('ভেরিফাইড')}else if(x!==null)toast('কোড ভুল')}
function upl(k,el){const f=el.files[0];if(!f)return;if(k!='photo'){me()[k]=1;save();render();return toast('আপলোড হয়েছে')}
 const r=new FileReader();r.onload=()=>{const i=new Image();i.onload=()=>{const c=document.createElement('canvas');c.width=c.height=160;const s=Math.min(i.width,i.height);c.getContext('2d').drawImage(i,(i.width-s)/2,(i.height-s)/2,s,s,0,0,160,160);const u=me();u.photo=1;u.img=c.toDataURL('image/jpeg',.8);save();render();toast('ছবি আপডেট হয়েছে')};i.src=r.result};r.readAsDataURL(f)}
function prof(){const u=me();if(!u)return'<div class="glass card"><h2>প্রোফাইল</h2><p class="sub">প্রোফাইল দেখতে লগইন বা রেজিস্ট্রেশন করুন।</p><br><button class="btn" onclick="reg()">রেজিস্ট্রেশন</button> <button class="btn o" onclick="login()">লগইন</button></div>';
 const f=u.role=='f',chk=[u.photo,u.doc,u.bio,u.loc,f?u.title:u.company,f?u.skills:1,f?u.rate:1,verified(u)],pc=Math.round(chk.filter(Boolean).length/chk.length*100);
 return`<div class="cols"><div class="glass card" style="text-align:center">${av(u,96)}<h3 style="margin-top:8px">${esc(u.id)}</h3><p class="sub">${f?'ফ্রিল্যান্সার':'ক্লায়েন্ট'}${u.company?' · '+esc(u.company):''}</p><p>${okv(u)?'<span class="vb">✔ ভেরিফায়েড</span>':'<span class="st">ভেরিফিকেশন বাকি</span>'}</p><label class="btn s" style="display:inline-block;margin:8px 0">ছবি পরিবর্তন<input type="file" accept="image/*" hidden onchange="upl('photo',this)"></label><div class="bar"><i style="width:${pc}%"></i></div><p class="sub" style="font-size:13px">প্রোফাইল ${bn(pc)}% সম্পূর্ণ</p><button class="btn o s" onclick="viewP('${u.id}')">পাবলিক প্রোফাইল দেখুন</button></div>
<div class="glass card"><h2>প্রোফাইল তথ্য</h2>${f?`<label>পেশাগত শিরোনাম</label><input id="pt1" value="${esc(u.title||'')}" placeholder="যেমন: গ্রাফিক ডিজাইনার">`:`<label>কোম্পানি / প্রতিষ্ঠানের নাম</label><input id="pco" value="${esc(u.company||'')}">`}<label>${f?'নিজের সম্পর্কে':'প্রতিষ্ঠান সম্পর্কে'}</label><textarea id="pb" rows="3">${esc(u.bio||'')}</textarea><label>অবস্থান (জেলা/শহর)</label><input id="pl" value="${esc(u.loc||'')}">${f?`<label>শুরুর রেট (৳)</label><input id="pr" type="number" value="${u.rate||''}"><label>ভাষা</label><input id="pg" value="${esc(u.lang||'')}" placeholder="বাংলা, ইংরেজি"><label>দক্ষতার ক্ষেত্র (একাধিক বাছাই করুন)</label><select id="sk" multiple size="6">${CATS.map(c=>`<option ${(u.skills||'').includes(c)?'selected':''}>${c}</option>`).join('')}</select>`:''}<p class="sub" style="font-size:12px">প্রোফাইলে ফোন, ইমেইল বা সোশ্যাল মিডিয়ার তথ্য দেওয়া যাবে না।</p><button class="btn" onclick="saveProf()">প্রোফাইল সেভ করুন</button></div></div>
${f?`<div class="glass card"><div class="row"><h2 style="margin:0">পোর্টফোলিও</h2><button class="btn s sp" onclick="addPort()">+ কাজ যোগ করুন</button></div>${(u.port||[]).map((x,i)=>`<div class="row" style="margin-top:6px">• ${esc(x.t)}<button class="btn o s sp" onclick="delPort(${i})">মুছুন</button></div>`).join('')||'<p class="sub">আপনার সেরা কাজগুলো যোগ করুন।</p>'}</div>`:''}`}
function saveProf(){const u=me(),g=id=>$(id)?$(id).value.trim():'';const all=g('pt1')+' '+g('pb')+' '+g('pl')+' '+g('pg');if(bad(all))return toast('প্রোফাইলে যোগাযোগের তথ্য দেওয়া যাবে না');
 u.bio=g('pb');u.loc=g('pl');if(u.role=='f'){u.title=g('pt1');u.rate=+g('pr')||0;u.lang=g('pg');u.skills=[...$('sk').selectedOptions].map(o=>o.value).join(', ')}else u.company=g('pco');save();render();toast('প্রোফাইল সেভ হয়েছে')}
function addPort(){const t=(prompt('কাজের নাম')||'').trim();if(!t)return;const l=(prompt('লিংক (ঐচ্ছিক, https://...)')||'').trim();if(bad(t)||(l&&!/^https?:\/\//.test(l)))return toast('শিরোনাম বা লিংক সঠিক নয়');me().port=me().port||[];me().port.push({t,l});save();render()}
function delPort(i){me().port.splice(i,1);save();render()}
function dep(){const u=me(),a=+v('da');if(!a||!v('dt').trim())return toast('পরিমাণ ও TrxID দিন');u.tx.push({k:v('dm'),a,n:v('dt').trim(),s:'p'});save();render();toast('জমা সাবমিট হয়েছে, যাচাই চলছে')}
function vtx(i){const u=me(),t=u.tx[i];t.s='ok';u.wallet+=t.a;note(u.id,'৳'+t.a+' ওয়ালেটে যুক্ত হয়েছে');save();render()}
function buyC(n,p){const u=me();if(!u||u.role!='f')return toast('শুধু ফ্রিল্যান্সার কানেক্ট কিনতে পারবেন');if(u.wallet<p)return toast('ওয়ালেটে টাকা কম। আগে জমা দিন');u.wallet-=p;u.connects+=n;save();render();toast(bn(n)+' কানেক্ট যুক্ত হয়েছে')}
function skills(){me().skills=[...$('sk').selectedOptions].map(o=>o.value).join(', ');save();toast('সেভ হয়েছে')}
function promo(){const u=me();if(u.wallet<50)return toast('ওয়ালেটে ৳৫০ নেই');u.wallet-=50;u.promo=1;save();render()}
function adBuy(){const u=me();if(u.wallet<100)return toast('ওয়ালেটে ৳১০০ নেই');if(!v('at'))return toast('শিরোনাম দিন');u.wallet-=100;S.ads.push({t:v('at'),v:v('av'),d:v('ad')});save();render()}
function postJob(){const u=need();if(!u)return;if(!v('jt')||!(+v('jb')>0))return toast('শিরোনাম ও বাজেট দিন');S.jobs.push({id:S.jid++,t:v('jt'),c:v('jc'),b:+v('jb'),d:v('jd'),by:u.id,st:'open',ap:[],hire:null,chat:[],files:[],rv:{}});save();render()}
function apply(id){const u=need();if(!u)return;if(u.connects<1)return toast('কানেক্ট শেষ। প্যাকেজ কিনুন');const j=S.jobs.find(x=>x.id==id);u.connects--;j.ap.push(u.id);note(j.by,u.id+' আপনার কাজে আবেদন করেছেন: '+j.t);save();render()}
function hire(id,f){const u=need();if(!u)return;const j=S.jobs.find(x=>x.id==id);if(u.wallet<j.b)return toast('এসক্রোর জন্য ওয়ালেটে ৳'+bn(j.b)+' দরকার');u.wallet-=j.b;j.hire=f;j.st='progress';note(f,'আপনাকে নিয়োগ দেওয়া হয়েছে: '+j.t);save();render();toast('টাকা এসক্রোতে রাখা হয়েছে')}
function submitW(id,el){if(!el.files[0])return;const j=S.jobs.find(x=>x.id==id);j.files.push(el.files[0].name);j.st='review';note(j.by,'কাজ জমা হয়েছে: '+j.t);save();render()}
function confirmW(id){const j=S.jobs.find(x=>x.id==id),f=U(j.hire),net=j.b*(1-FEE/100);f.wallet+=net;j.st='done';note(f.id,'৳'+bn(net)+' ওয়ালেটে যুক্ত হয়েছে ('+bn(FEE)+'% ফি বাদে)। কাজ: '+j.t);save();render();toast('পেমেন্ট দেওয়া হয়েছে')}
function review(id){const u=me(),j=S.jobs.find(x=>x.id==id),s=+prompt('রেটিং (১-৫)');if(!(s>=1&&s<=5))return;const c=prompt('মন্তব্য')||'';const o=U(u.id==j.by?j.hire:j.by);o.rev.push({s,c});j.rv[u.id]=1;note(o.id,'আপনি একটি নতুন রিভিউ পেয়েছেন');save();render()}
function chat(id){const j=S.jobs.find(x=>x.id==id),u=me();modal(`<h2>${esc(j.t)}</h2><p class="sub" style="font-size:12px">ফোন, ইমেইল বা সোশ্যাল মিডিয়ার তথ্য শেয়ার নিষিদ্ধ।</p><div style="max-height:40vh;overflow:auto">${j.chat.map(m=>`<div class="msg ${m.f==u.id?'me':''}"><small>${m.f}</small><br>${esc(m.t)}</div>`).join('')||'<p class="sub">কথা শুরু করুন।</p>'}</div><input id="cm" placeholder="বার্তা লিখুন"><button class="btn" onclick="send(${id})">পাঠান</button>`)}
function send(id){const t=v('cm').trim();if(!t)return;if(bad(t))return toast('যোগাযোগের তথ্য শেয়ার করা যাবে না');const j=S.jobs.find(x=>x.id==id),u=me();j.chat.push({f:u.id,t});note(u.id==j.by?(j.hire||j.ap[0]):j.by,'নতুন বার্তা: '+j.t);save();chat(id)}
function postProd(){const u=need();if(!u)return;if(!v('pt')||!(+v('pp')>0))return toast('নাম ও দাম দিন');S.prods.push({t:v('pt'),p:+v('pp'),d:v('pd'),by:u.id});save();render()}
function buyP(i){const u=need();if(!u)return;const p=S.prods[i];if(p.by==u.id)return toast('নিজের পণ্য কিনতে পারবেন না');if(u.wallet<p.p)return toast('ওয়ালেটে পর্যাপ্ত টাকা নেই');u.wallet-=p.p;U(p.by).wallet+=p.p*(1-FEE/100);p.sold=1;note(p.by,'আপনার পণ্য বিক্রি হয়েছে: '+p.t);save();render();toast('কেনা সম্পন্ন')}
render();

